def transform(grid):
    h,w=len(grid),len(grid[0])
    # Separators are full-length solid-color lines; use the color appearing on both axes.
    row_lines=[r for r in range(h) if len(set(grid[r]))==1]
    col_lines=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1]
    sep=grid[row_lines[0]][0] if row_lines else grid[0][col_lines[0]]
    bg_counts={}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v!=sep: bg_counts[v]=bg_counts.get(v,0)+1
    bg=max(bg_counts,key=bg_counts.get)
    marked=[v for v in bg_counts if v!=bg]
    mark=marked[0] if marked else None
    def spans(n, lines):
        out=[]; start=0
        for i in lines:
            if start<i: out.append((start,i))
            start=i+1
        if start<n: out.append((start,n))
        return out
    rs=spans(h,row_lines); cs=spans(w,col_lines)
    out=[]
    for r0,r1 in rs:
        row=[]
        for c0,c1 in cs:
            cells={(r,c) for r in range(r0,r1) for c in range(c0,c1) if grid[r][c]==mark}
            hit=any((r+1,c) in cells or (r,c+1) in cells for r,c in cells)
            row.append(1 if hit else bg)
        out.append(row)
    return out
